// Writes src/app/theme.css from src/lib/theme.ts. Run: node --import tsx scripts/generate-theme-css.ts
// tests/theme.test.ts fails if the file is out of date.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { PRESETS, TOKEN_NAMES, cssName, type Palette } from "../src/lib/theme";

const block = (selector: string, p: Palette, scheme: string) =>
  `${selector} {\n  color-scheme: ${scheme};\n${TOKEN_NAMES.map(t => `  ${cssName(t)}: ${p[t]};`).join("\n")}\n}\n`;

export function themeCss() {
  return [
    "/* Generated by scripts/generate-theme-css.ts from src/lib/theme.ts. Do not edit by hand. */",
    "/* Every colour in the app reads these --theme-* tokens. Custom colours are applied inline on <html>. */",
    block(':root,\n:root[data-palette="signature"]', PRESETS.signature.light, "light"),
    block(':root[data-mode="dark"],\n:root[data-palette="signature"][data-mode="dark"]', PRESETS.signature.dark, "dark"),
    block(':root[data-palette="berry"]', PRESETS.berry.light, "light"),
    block(':root[data-palette="berry"][data-mode="dark"]', PRESETS.berry.dark, "dark"),
    `:root[data-palette="custom"] { color-scheme: light; }\n:root[data-palette="custom"][data-mode="dark"] { color-scheme: dark; }\n`,
  ].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(new URL("../src/app/theme.css", import.meta.url), themeCss());
  console.log("Wrote src/app/theme.css");
}
